import {m34abProject,reviewM34Fixture} from "./m34ab-fixtures";
import {declaredStructureSchema} from "../declared-structure";

/** Explicit synthetic survey for the UI/HTTP integration campaign.
 * Two 5 m fixed-ended purlins, split at midspan, joined by real edge members.
 * Four concrete interfaces are declared inputs, never generated by the app.
 * Uniform 0.2 kN/m² on 20 m² gives 4000 N and -q L^4/(384 EI) at midspan.
 */
export function generalIntegrationProject(){
  const p=m34abProject();
  p.name="Integração geral — cobertura física declarada";
  p.client="Ensaio sintético independente, sem aprovação de obra";
  p.workspace.physicalStructure=declaredStructureSchema.parse({
    schema_version:"jpn.declared-structure/1",source:"declared",units:"mm",
    provenance:"Seis nós medidos sintéticos e seis barras explicitamente declaradas",
    revision:"INTEGRATION-SURVEY-1",
    nodes:[
      {id:"A0",x:0,y:0,z:3000},{id:"AM",x:0,y:2500,z:3000},{id:"A5",x:0,y:5000,z:3000},
      {id:"B0",x:4000,y:0,z:3400},{id:"BM",x:4000,y:2500,z:3400},{id:"B5",x:4000,y:5000,z:3400},
    ],
    pieces:[
      {id:"P1A",role:"purlin",start:"A0",end:"AM"},{id:"P1B",role:"purlin",start:"AM",end:"A5"},
      {id:"P2A",role:"purlin",start:"B0",end:"BM"},{id:"P2B",role:"purlin",start:"BM",end:"B5"},
      {id:"CH0",role:"topChord",start:"A0",end:"B0"},{id:"CH5",role:"topChord",start:"A5",end:"B5"},
    ],
  });
  const d=p.workspace.spatialPreparation!;
  const pieces=p.workspace.physicalStructure.pieces.map(v=>v.id);
  d.physicalCatalog!.materials=d.physicalCatalog!.materials.filter(v=>v.id==="STEEL");
  d.physicalCatalog!.sections=d.physicalCatalog!.sections.filter(v=>v.id==="S1");
  d.physicalCatalog!.assignments=pieces.map(pieceId=>({pieceId,materialId:"STEEL",sectionId:"S1",rotationDeg:0}));
  d.memberKinds=pieces.map(pieceId=>({pieceId,kind:"frame"}));
  d.memberConnections=pieces.map(pieceId=>({pieceId,start:"rigid",end:"rigid"}));
  d.supports=["A0","A5","B0","B5"].map(nodeId=>({nodeId,dofs:["fixed","fixed","fixed","fixed","fixed","fixed"]}));
  d.supportInterfaces=d.supports.map(s=>({
    nodeId:s.nodeId,side:s.nodeId.startsWith("A")?"A":"B",kind:"existing-concrete",dofs:s.dofs,
    source:"Interfaces de concreto explícitas da referência analítica sintética",
    revision:"INTEGRATION-SUPPORT-1",loadPath:"Terça contínua -> nó de borda -> interface declarada",
    restraintBasis:"Engaste de referência explicitamente informado; capacidade não verificada",
    reviewStatus:"site-reviewed",
  }));
  d.cases=[{id:"AREA",source:"Pressão vertical sintética declarada; sem enquadramento normativo"}];
  d.combinations=[{id:"ELASTIC",factors:{AREA:1}}];
  d.loads=[];
  d.connectionsReview="Continuidade rígida explicitamente declarada nos dois segmentos de cada terça";
  d.lateralSystem="Quatro interfaces físicas explícitas; os nós centrais AM e BM permanecem livres";
  d.loadPathReview="Pano medido -> quatro segmentos reais de terça -> quatro interfaces de concreto";
  // Roof faces and actions are entered through the actual user interface.
  delete d.loading;
  delete d.physicalRoofFaces;
  return reviewM34Fixture(p);
}
